    <button id="reset-btn" class="reset-btn">Reset Game</button>

    <script>
        // Game state
        const defaultState = {
            hunger: 50,
            happiness: 80,
            energy: 80,
            health: 100,
            boredom: 30,
            lastUpdate: Date.now(),
            age: 0,
            isDead: false,
            isSleeping: false
        };

        let gameState = {...defaultState};
        let gameInterval;
        let ageInterval;
        let particleInterval;

        // DOM elements
        const petElement = document.getElementById('pet');
        const statusElement = document.getElementById('status');
        const ageDisplay = document.getElementById('age-display');
        const particlesContainer = document.getElementById('particles');

        // Need fills
        const needFills = {
            hunger: document.getElementById('hunger-fill'),
            happiness: document.getElementById('happiness-fill'),
            energy: document.getElementById('energy-fill'),
            health: document.getElementById('health-fill'),
            boredom: document.getElementById('boredom-fill')
        };

        // Buttons
        const buttons = {
            feed: document.getElementById('feed-btn'),
            play: document.getElementById('play-btn'),
            heal: document.getElementById('heal-btn'),
            sleep: document.getElementById('sleep-btn'),
            clean: document.getElementById('clean-btn'),
            reset: document.getElementById('reset-btn')
        };

        // Initialize the game
        function initGame() {
            loadGame();
            updatePetAppearance();
            updateNeedMeters();
            updateButtons();

            // Start game loop
            gameInterval = setInterval(gameLoop, 1000);
            ageInterval = setInterval(updateAge, 60000); // 1 minute = 1 day
            particleInterval = setInterval(createParticles, 200);

            // Set up event listeners
            buttons.feed.addEventListener('click', () => feedPet());
            buttons.play.addEventListener('click', () => playWithPet());
            buttons.heal.addEventListener('click', () => healPet());
            buttons.sleep.addEventListener('click', () => toggleSleep());
            buttons.clean.addEventListener('click', () => cleanPet());
            buttons.reset.addEventListener('click', () => resetGame());

            // Initial status update
            updateStatus();
        }

        // Game loop
        function gameLoop() {
            if (gameState.isDead) return;

            const now = Date.now();
            const timePassed = now - gameState.lastUpdate;
            gameState.lastUpdate = now;

            // Decrease needs over time
            const decayRate = timePassed / 1000; // Convert to seconds

            // Hunger increases over time
            gameState.hunger = Math.min(100, gameState.hunger + decayRate * 0.5);

            // Boredom increases over time
            gameState.boredom = Math.min(100, gameState.boredom + decayRate * 0.3);

            // Energy decreases over time (unless sleeping)
            if (!gameState.isSleeping) {
                gameState.energy = Math.max(0, gameState.energy - decayRate * 0.2);
            } else {
                // Energy recovers while sleeping
                gameState.energy = Math.min(100, gameState.energy + decayRate * 0.8);
            }

            // Health decreases if needs are too low
            if (gameState.hunger > 80 || gameState.boredom > 80 || gameState.energy < 20) {
                gameState.health = Math.max(0, gameState.health - decayRate * 0.1);
            }

            // Happiness decreases if needs are not met
            if (gameState.hunger > 60 || gameState.boredom > 60 || gameState.energy < 40) {
                gameState.happiness = Math.max(0, gameState.happiness - decayRate * 0.2);
            }

            // Check if pet died
            if (gameState.health <= 0 || gameState.hunger >= 100 || gameState.boredom >= 100) {
                gameState.isDead = true;
                gameState.happiness = 0;
                gameState.health = 0;
                clearInterval(gameInterval);
                clearInterval(ageInterval);
                clearInterval(particleInterval);
                updateStatus();
            }

            updatePetAppearance();
            updateNeedMeters();
            updateButtons();
            saveGame();
        }

        // Update pet's appearance based on state
        function updatePetAppearance() {
            // Reset all classes
            petElement.className = 'pet';

            if (gameState.isDead) {
                petElement.classList.add('dead');
                return;
            }

            // Determine primary state
            if (gameState.health < 30) {
                petElement.classList.add('sick');
            } else if (gameState.hunger > 70) {
                petElement.classList.add('hungry');
            } else if (gameState.boredom > 70) {
                petElement.classList.add('bored');
            } else if (gameState.energy < 30) {
                petElement.classList.add('tired');
            } else if (gameState.happiness > 70) {
                petElement.classList.add('happy');
            }

            if (gameState.isSleeping) {
                petElement.classList.add('tired');
            }
        }

        // Update need meters
        function updateNeedMeters() {
            for (const [need, fill] of Object.entries(needFills)) {
                const value = gameState[need];
                fill.style.width = `${value}%`;

                // Set color based on value
                if (value > 80) {
                    fill.style.backgroundColor = `var(--${need === 'happiness' ? 'happy' : need}-color)`;
                } else if (value > 60) {
                    fill.style.backgroundColor = `color-mix(in srgb, var(--${need === 'happiness' ? 'happy' : need}-color) 70%, var(--neutral-color))`;
                } else if (value > 40) {
                    fill.style.backgroundColor = `color-mix(in srgb, var(--${need === 'happiness' ? 'happy' : need}-color) 40%, var(--neutral-color))`;
                } else {
                    fill.style.backgroundColor = 'var(--neutral-color)';
                }
            }
        }

        // Update button states
        function updateButtons() {
            buttons.feed.disabled = gameState.isDead || gameState.isSleeping;
