  stats: { vitality: 100, hunger: 80, happiness: 70, cleanliness: 90, bond: 15 },
  isSleeping: false,
  log: []
};

let state = loadState();

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return structuredClone(defaultState);
    const s = JSON.parse(raw);
    // Apply offline decay
    const now = Date.now();
    const elapsed = Math.min((now - (s.lastTick || now)) / 1000, 86400); // cap 1 day
    applyDecay(s, elapsed);
    s.lastTick = now;
    return s;
  } catch(e) {
    return structuredClone(defaultState);
  }
}

function saveState() {
  state.lastTick = Date.now();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function applyDecay(s, seconds) {
  const cycles = seconds / 5; // decay tick is 5s
  s.stats.hunger = Math.max(0, s.stats.hunger - 0.6 * cycles);
  s.stats.happiness = Math.max(0, s.stats.happiness - 0.4 * cycles);
  s.stats.cleanliness = Math.max(0, s.stats.cleanliness - 0.25 * cycles);
  // Vitality logic
  if (s.stats.hunger < 20 || s.stats.happiness < 20 || s.stats.cleanliness < 15) {
    s.stats.vitality = Math.max(0, s.stats.vitality - 0.5 * cycles);
  } else if (s.stats.hunger > 50 && s.stats.happiness > 50) {
    s.stats.vitality = Math.min(100, s.stats.vitality + 0.2 * cycles);
  }
  if (s.isSleeping) {
    s.stats.vitality = Math.min(100, s.stats.vitality + 0.4 * cycles);
    s.stats.happiness = Math.min(100, s.stats.happiness + 0.1 * cycles);
  }
}

// ---------- Canvas Setup ----------
const canvas = document.getElementById('pet');
const ctx = canvas.getContext('2d');
let W = 0, H = 0, cx = 0, cy = 0, dpr = 1;

function resize() {
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  W = rect.width; H = rect.height;
  cx = W / 2; cy = H / 2;
}
window.addEventListener('resize', resize);

// ---------- Pet Entity ----------
const pet = {
  x: 0, y: 0,
  baseRadius: 90,
  radius: 90,
  breath: 0,
  blinkTimer: 0,
  blink: 0,
  pupilOffset: { x: 0, y: 0 },
  mood: 'neutral',
  reaction: null,     // {type, t, duration}
  shake: 0,
  glow: 0,            // extra glow from interactions
  particles: [],
  wisps: [],
  effects: []
};

// Initialize orbiting particles
for (let i = 0; i < 28; i++) {
  pet.particles.push({
    angle: Math.random() * Math.PI * 2,
    radius: 110 + Math.random() * 60,
    speed: 0.2 + Math.random() * 0.5,
    size: 1 + Math.random() * 2.5,
    phase: Math.random() * Math.PI * 2,
    hueShift: Math.random()
  });
}

// Initialize wisps
for (let i = 0; i < 7; i++) {
  pet.wisps.push({
    angle: (i / 7) * Math.PI * 2,
    length: 50 + Math.random() * 30,
    phase: Math.random() * Math.PI * 2,
    speed: 0.8 + Math.random() * 0.4
  });
}

// ---------- Mouse ----------
const mouse = { x: -999, y: -999, inside: false, down: false };
canvas.addEventListener('mousemove', e => {
  const r = canvas.getBoundingClientRect();
  mouse.x = e.clientX - r.left;
  mouse.y = e.clientY - r.top;
  mouse.inside = true;
});
canvas.addEventListener('mouseleave', () => { mouse.inside = false; mouse.x = -999; mouse.y = -999; });
canvas.addEventListener('click', e => {
  const r = canvas.getBoundingClientRect();
  const mx = e.clientX - r.left, my = e.clientY - r.top;
  const dx = mx - pet.x, dy = my - pet.y;
  if (Math.sqrt(dx*dx + dy*dy) < pet.radius * 1.2) {
    triggerAction('pet');
  }
});

// ---------- Mood Computation ----------
function computeMood() {
  if (state.isSleeping) return 'sleeping';
  if (state.stats.vitality < 25) return 'critical';
  if (state.stats.hunger < 25) return 'hungry';
  if (state.stats.cleanliness < 25) return 'dirty';
  if (state.stats.happiness < 25) return 'sad';
  if (state.stats.happiness > 75 && state.stats.hunger > 60) return 'happy';
  return 'neutral';
}

const moodColors = {
  happy:     { core: '#ffd166', mid: '#ffb347', glow: '#ff8c42', aura: '#ffb347' },
  neutral:   { core: '#a7f3d0', mid: '#5eead4', glow: '#2dd4bf', aura: '#5eead4' },
  sad:       { core: '#94a3b8', mid: '#64748b', glow: '#475569', aura: '#7c8aa5' },
  hungry:    { core: '#fda4af', mid: '#f87171', glow: '#ef4444', aura: '#f87171' },
  dirty:     { core: '#d6b89a', mid: '#a8896c', glow: '#826c54', aura: '#a8896c' },
  critical:  { core: '#f87171', mid: '#dc2626', glow: '#991b1b', aura: '#ef4444' },
  sleeping:  { core: '#c4b5fd', mid: '#a78bfa', glow: '#7c6f9c', aura: '#a78bfa' }
};

// ---------- Effects Spawners ----------
function spawnFood() {
