}

function spawnHearts() {
  for (let i = 0; i < 6; i++) {
    pet.effects.push({
      type: 'heart',
      x: pet.x + (Math.random() - 0.5) * 80,
      y: pet.y - 20,
      vx: (Math.random() - 0.5) * 0.8,
      vy: -1 - Math.random() * 0.8,
      life: 1, ttl: 1.8,
