}

function spawnBubbles() {
  for (let i = 0; i < 18; i++) {
    pet.effects.push({
      type: 'bubble',
      x: pet.x + (Math.random() - 0.5) * 140,
      y: pet.y + 60 + Math.random() * 40,
      vx: (Math.random() - 0.5) * 0.4,
