    pet.effects.push({
      type: 'spark',
      x: pet.x, y: pet.y,
      vx: Math.cos(a) * sp,
      vy: Math.sin(a) * sp,
      life: 1, ttl: 0.8 + Math.random() * 0.4,
      size: 2 + Math.random() * 2,
      color: color || '#ffb347'
    });
