}

function spawnZ() {
  pet.effects.push({
    type: 'z',
    x: pet.x + 30 + (Math.random() - 0.5) * 20,
    y: pet.y - 40,
    vx: 0.3, vy: -0.6,
    life: 1, ttl: 2.5,
    size: 14 + Math.random() * 6,
    rot: -0.2
  });
