// ---------- Actions ----------
const actionCooldowns = {};
function triggerAction(action) {
  const now = Date.now();
  if (actionCooldowns[action] && now - actionCooldowns[action] < 600) return;
  actionCooldowns[action] = now;

  if (action === 'feed' && !state.isSleeping) {
    if (state.stats.hunger >= 98) { toast('Nova is full.'); return; }
    state.stats.hunger = Math.min(100, state.stats.hunger + 25);
    state.stats.bond = Math.min(100, state.stats.bond + 2);
    pet.reaction = { type: 'eat', t: 0, duration: 1.5 };
    spawnFood();
    addLog('Fed Nova');
    toast('Nom nom — satiety rising');
  }
  else if (action === 'play' && !state.isSleeping) {
    if (state.stats.vitality < 15) { toast('Nova is too tired.'); return; }
    state.stats.happiness = Math.min(100, state.stats.happiness + 22);
    state.stats.hunger = Math.max(0, state.stats.hunger - 6);
    state.stats.vitality = Math.max(0, state.stats.vitality - 4);
    state.stats.bond = Math.min(100, state.stats.bond + 4);
    pet.reaction = { type: 'play', t: 0, duration: 1.8 };
    spawnSparkles(24, '#f472b6');
    addLog('Played with Nova');
    toast('Joy surges through the void');
  }
  else if (action === 'clean' && !state.isSleeping) {
    state.stats.cleanliness = Math.min(100, state.stats.cleanliness + 30);
    state.stats.bond = Math.min(100, state.stats.bond + 1);
    pet.reaction = { type: 'clean', t: 0, duration: 2 };
    spawnBubbles();
    addLog('Cleansed Nova');
    toast('Purity restored');
  }
  else if (action === 'pet') {
    state.stats.happiness = Math.min(100, state.stats.happiness + 6);
    state.stats.bond = Math.min(100, state.stats.bond + 3);
    pet.reaction = { type: 'pet', t: 0, duration: 1 };
    pet.glow = 1;
    spawnHearts();
    addLog('Soothed Nova');
  }
  else if (action === 'sleep') {
    state.isSleeping = !state.isSleeping;
    pet.reaction = { type: state.isSleeping ? 'sleep' : 'wake', t: 0, duration: 1 };
    addLog(state.isSleeping ? 'Nova drifts to sleep' : 'Nova awakens');
    toast(state.isSleeping ? 'Drifting into the deep…' : 'Awakening');
    document.querySelector('[data-action="sleep"]').classList.toggle('active', state.isSleeping);
  }
  else if (action === 'reset') {
    if (!confirm) {} // no confirm dialog
    state = structuredClone(defaultState);
    state.born = Date.now();
    state.lastTick = Date.now();
    saveState();
    addLog('A new entity is born');
    toast('A new entity has manifested');
    document.querySelector('[data-action="sleep"]').classList.remove('active');
  }
  saveState();
  updateUI();
}

document.querySelectorAll('.act').forEach(btn => {
  btn.addEventListener('click', () => triggerAction(btn.dataset.action));
  btn.addEventListener('mousemove', e => {
    const r = btn.getBoundingClientRect();
    btn.style.setProperty('--mx', (e.clientX - r.left) + 'px');
    btn.style.setProperty('--my', (e.clientY - r.top) + 'px');
  });
});

// ---------- Toast & Log ----------
function toast(msg) {
  const wrap = document.getElementById('toasts');
  const el = document.createElement('div');
  el.className = 'toast';
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(() => el.remove(), 2700);
}

function addLog(text) {
  const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  state.log.unshift({ time, text });
  state.log = state.log.slice(0, 30);
  renderLog();
}

function renderLog() {
  const el = document.getElementById('log');
  el.innerHTML = state.log.map(e =>
    `<div class="log-entry"><span class="t">${e.time}</span>${e.text}</div>`
  ).join('');
}

// ---------- UI Update ----------
function updateUI() {
  // Stats
  document.querySelectorAll('.stat').forEach(stat => {
    const key = stat.dataset.key;
    const val = Math.round(state.stats[key]);
    stat.querySelector('.stat-val').textContent = val;
    stat.querySelector('.stat-fill').style.width = val + '%';
    stat.classList.toggle('low', val < 25);
  });

  // Age
  const ageS = Math.floor((Date.now() - state.born) / 1000);
  let ageStr;
  if (ageS < 60) ageStr = ageS + 's';
  else if (ageS < 3600) ageStr = Math.floor(ageS/60) + 'm ' + (ageS%60) + 's';
  else ageStr = Math.floor(ageS/3600) + 'h ' + Math.floor((ageS%3600)/60) + 'm';
  document.getElementById('petAge').textContent = ageStr;

  // Bond level
  const bondLvls = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII'];
  const bondIdx = Math.min(bondLvls.length - 1, Math.floor(state.stats.bond / 15));
  document.getElementById('petBondLvl').textContent = bondLvls[bondIdx];

  // Status
  const mood = computeMood();
  const statusMap = {
    happy: ['Radiant', 'Basking in warmth and light.'],
    neutral: ['Idle', 'Observing the void.'],
    sad: ['Despondent', 'Light flickers low. Play, perhaps?'],
    hungry: ['Starving', 'Hunger gnaws at the core.'],
    dirty: ['Tarnished', 'Dust dims the glow. Cleanse it.'],
    critical: ['Fading', 'Vitality nears zero. Act now.'],
    sleeping: ['Dreaming', 'Recharging in the deep.']
  };
  const [title, sub] = statusMap[mood];
  const statusEl = document.getElementById('petStatus');
  statusEl.textContent = title;
  document.getElementById('petStatusSub').textContent = sub;
  const colors = {
    happy: '#ffb347', neutral: '#5eead4', sad: '#7c8aa5',
    hungry: '#f87171', dirty: '#a8896c', critical: '#ef4444', sleeping: '#a78bfa'
  };
  statusEl.style.color = colors[mood];
}

// ---------- Rendering ----------
let lastT = performance.now();
let zTimer = 0;

function render(now) {
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;

  // Decay tick (every 5s)
  if (now - (render._lastDecay || 0) > 5000) {
    applyDecay(state, 5);
    render._lastDecay = now;
    saveState();
    updateUI();
  }

  // Update pet position
  pet.x = cx;
  pet.y = cy + Math.sin(now * 0.0008) * 8;

  // Breathing
  pet.breath += dt;
  const breathScale = 1 + Math.sin(pet.breath * 1.5) * 0.04;
  const sleepScale = state.isSleeping ? 0.88 : 1;
  pet.radius = pet.baseRadius * breathScale * sleepScale;

  // Reaction timer
  if (pet.reaction) {
    pet.reaction.t += dt;
    if (pet.reaction.t > pet.reaction.duration) pet.reaction = null;
  }

  // Shake (during play)
  pet.shake *= 0.9;
  if (pet.reaction && pet.reaction.type === 'play') {
    pet.shake = Math.sin(pet.reaction.t * 30) * 4 * (1 - pet.reaction.t / pet.reaction.duration);
  }

  // Glow decay
  pet.glow *= 0.95;

  // Blink
  pet.blinkTimer += dt;
  if (pet.blinkTimer > 3 + Math.random() * 2) {
    pet.blink = 1;
    pet.blinkTimer = 0;
  }
  pet.blink = Math.max(0, pet.blink - dt * 8);

  // Pupil tracking
  if (mouse.inside && !state.isSleeping) {
    const dx = mouse.x - pet.x, dy = mouse.y - pet.y;
    const d = Math.sqrt(dx*dx + dy*dy);
    const max = 6;
    pet.pupilOffset.x += ((dx / Math.max(d, 1)) * Math.min(max, d * 0.1) - pet.pupilOffset.x) * 0.15;
    pet.pupilOffset.y += ((dy / Math.max(d, 1)) * Math.min(max, d * 0.1) - pet.pupilOffset.y) * 0.15;
  } else {
    pet.pupilOffset.x *= 0.9;
    pet.pupilOffset.y *= 0.9;
  }

  // Mood
  pet.mood = computeMood();

  // Sleep Z particles
  if (state.isSleeping) {
    zTimer += dt;
    if (zTimer > 0.8) { spawnZ(); zTimer = 0; }
  }

  // Clear
  ctx.clearRect(0, 0, W, H);

  // Draw aura ring
  drawAura(now);

  // Draw wisps (behind body)
  drawWisps(now);

  // Draw orbiting particles (behind)
  drawParticles(now, false);

  // Draw body
  drawBody(now);

  // Draw eyes
  drawEyes();

  // Draw orbiting particles (front)
  drawParticles(now, true);

  // Draw effects
  drawEffects(dt);

  // Draw cursor influence
  if (mouse.inside && !state.isSleeping) {
    const dx = mouse.x - pet.x, dy = mouse.y - pet.y;
    const d = Math.sqrt(dx*dx + dy*dy);
    if (d < 200) {
      ctx.save();
      ctx.globalAlpha = (1 - d / 200) * 0.3;
      ctx.strokeStyle = moodColors[pet.mood].aura;
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 4]);
      ctx.beginPath();
      ctx.moveTo(pet.x, pet.y);
      ctx.lineTo(mouse.x, mouse.y);
      ctx.stroke();
      ctx.restore();
    }
  }

  requestAnimationFrame(render);
}

function drawAura(now) {
  const c = moodColors[pet.mood];
  const pulse = 1 + Math.sin(now * 0.002) * 0.05;
  const r = pet.radius * 2.2 * pulse;
  const grad = ctx.createRadialGradient(pet.x, pet.y, pet.radius * 0.8, pet.x, pet.y, r);
  grad.addColorStop(0, hexToRgba(c.aura, 0.25));
  grad.addColorStop(0.5, hexToRgba(c.aura, 0.08));
  grad.addColorStop(1, hexToRgba(c.aura, 0));
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(pet.x, pet.y, r, 0, Math.PI * 2);
  ctx.fill();
}

function drawWisps(now) {
  const c = moodColors[pet.mood];
  const energy = state.stats.vitality / 100;
  ctx.save();
  ctx.translate(pet.x + pet.shake, pet.y);
  pet.wisps.forEach((w, i) => {
    const wave = Math.sin(now * 0.001 * w.speed + w.phase) * 0.3;
    const ang = w.angle + wave + now * 0.0001;
    const len = w.length * (0.7 + energy * 0.5) * (state.isSleeping ? 0.4 : 1);
    const startX = Math.cos(ang) * pet.radius * 0.9;
    const startY = Math.sin(ang) * pet.radius * 0.9;
    const endX = Math.cos(ang) * (pet.radius + len);
    const endY = Math.sin(ang) * (pet.radius + len);
    const ctrlAng = ang + 0.3;
    const ctrlX = Math.cos(ctrlAng) * (pet.radius + len * 0.6);
    const ctrlY = Math.sin(ctrlAng) * (pet.radius + len * 0.6);

    const grad = ctx.createLinearGradient(startX, startY, endX, endY);
    grad.addColorStop(0, hexToRgba(c.mid, 0.6));
    grad.addColorStop(1, hexToRgba(c.glow, 0));
    ctx.strokeStyle = grad;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.quadraticCurveTo(ctrlX, ctrlY, endX, endY);
    ctx.stroke();
  });
  ctx.restore();
}

function drawParticles(now, front) {
  const c = moodColors[pet.mood];
  const happiness = state.stats.happiness / 100;
  const visibleCount = Math.floor(pet.particles.length * (0.3 + happiness * 0.7));
  ctx.save();
  ctx.translate(pet.x + pet.shake, pet.y);
  pet.particles.forEach((p, i) => {
    if ((i % 2 === 0) !== front) return; // alternate front/back
    if (i >= visibleCount && !state.isSleeping) return;
    p.angle += p.speed * 0.01;
    const r = p.radius + Math.sin(now * 0.001 + p.phase) * 8;
    const x = Math.cos(p.angle) * r;
    const y = Math.sin(p.angle) * r * 0.7; // elliptical orbit
    const size = p.size * (0.8 + Math.sin(now * 0.003 + p.phase) * 0.3);
    const alpha = 0.4 + Math.sin(now * 0.002 + p.phase) * 0.3;
    const col = p.hueShift > 0.5 ? c.core : c.mid;
    ctx.fillStyle = hexToRgba(col, alpha);
    ctx.shadowColor = col;
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(x, y, Math.max(0.5, size), 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.shadowBlur = 0;
  ctx.restore();
}

function drawBody(now
